/**
 * Xero Node - Version 1
 * Discriminator: resource=contact, operation=create
 */


interface Credentials {
  xeroOAuth2Api: CredentialReference;
}

/** Create a contact */
export type XeroV1ContactCreateParams = {
  resource: 'contact';
  operation: 'create';
/**
 * Choose from the list, or specify an ID using an &lt;a href="https://docs.n8n.io/code/expressions/"&gt;expression&lt;/a&gt;
 * @loadOptionsMethod getTenants
 */
    organizationId: string | Expression<string>;
/**
 * Full name of contact/organisation
 */
    name: string | Expression<string>;
/**
 * Additional Fields
 * @default {}
 */
    additionalFields?: {
    /** A user defined account number
     */
    accountNumber?: string | Expression<string>;
    /** Addresses
     * @default {}
     */
    addressesUi?: {
        /** Address
     */
    addressesValues?: Array<{
      /** Type
       */
      type?: 'POBOX' | 'STREET' | Expression<string>;
      /** Line 1
       */
      line1?: string | Expression<string>;
      /** Line 2
       */
      line2?: string | Expression<string>;
      /** City
       */
      city?: string | Expression<string>;
      /** Region
       */
      region?: string | Expression<string>;
      /** Postal Code
       */
      postalCode?: string | Expression<string>;
      /** Country
       */
      country?: string | Expression<string>;
      /** Attention To
       */
      attentionTo?: string | Expression<string>;
    }>;
  };
    /** Bank account number of contact
     */
    bankAccountDetails?: string | Expression<string>;
    /** This field is read only on the Xero contact screen, used to identify contacts in external systems
     */
    contactNumber?: string | Expression<string>;
    /** Current status of a contact - see contact status types
     */
    contactStatus?: 'ACTIVE' | 'ARCHIVED' | 'GDPRREQUEST' | Expression<string>;
    /** Default currency for raising invoices against contact
     */
    defaultCurrency?: string | Expression<string>;
    /** Email address of contact person (umlauts not supported) (max length = 255)
     */
    emailAddress?: string | Expression<string>;
    /** First name of contact person (max length = 255)
     */
    firstName?: string | Expression<string>;
    /** Last name of contact person (max length = 255)
     */
    lastName?: string | Expression<string>;
    /** Phones
     * @default {}
     */
    phonesUi?: {
        /** Phones
     */
    phonesValues?: Array<{
      /** Type
       */
      phoneType?: 'DEFAULT' | 'DDI' | 'MOBILE' | 'FAX' | Expression<string>;
      /** Number
       */
      phoneNumber?: string | Expression<string>;
      /** Area Code
       */
      phoneAreaCode?: string | Expression<string>;
      /** Country Code
       */
      phoneCountryCode?: string | Expression<string>;
    }>;
  };
    /** The default purchases account code for contacts. Choose from the list, or specify an ID using an &lt;a href="https://docs.n8n.io/code/expressions/"&gt;expression&lt;/a&gt;.
     * @loadOptionsMethod getAccountCodes
     */
    purchasesDefaultAccountCode?: string | Expression<string>;
    /** The default sales account code for contacts. Choose from the list, or specify an ID using an &lt;a href="https://docs.n8n.io/code/expressions/"&gt;expression&lt;/a&gt;.
     * @loadOptionsMethod getAccountCodes
     */
    salesDefaultAccountCode?: string | Expression<string>;
    /** Skype user name of contact
     */
    skypeUserName?: string | Expression<string>;
    /** Tax number of contact
     */
    taxNumber?: string | Expression<string>;
    /** Store XeroNetworkKey for contacts
     */
    xeroNetworkKey?: string | Expression<string>;
  };
};

export type XeroV1ContactCreateOutput = {
  Addresses?: Array<{
    AddressType?: string;
    City?: string;
    Country?: string;
    PostalCode?: string;
    Region?: string;
  }>;
  BankAccountDetails?: string;
  ContactID?: string;
  ContactStatus?: string;
  EmailAddress?: string;
  HasValidationErrors?: boolean;
  IsCustomer?: boolean;
  IsSupplier?: boolean;
  Name?: string;
  Phones?: Array<{
    PhoneAreaCode?: string;
    PhoneCountryCode?: string;
    PhoneNumber?: string;
    PhoneType?: string;
  }>;
  UpdatedDateUTC?: string;
};

export type XeroV1ContactCreateNode = {
  type: 'n8n-nodes-base.xero';
  version: 1;
  config: NodeConfig<XeroV1ContactCreateParams> & { credentials?: Credentials };
  output?: Items<XeroV1ContactCreateOutput>;
};